type Parte = string | false | null | undefined;
const cx = (...partes: Parte[]) => partes.filter(Boolean).join(' ');

const item = (feita: boolean, urgente?: boolean) =>
  cx('rounded p-2', feita && 'line-through opacity-60', urgente && 'border-red-600');

console.log(item(false));
console.log(item(true));
console.log(item(false, true));

