const abrir = document.querySelector<HTMLButtonElement>('#abrir');
const dialogo = document.querySelector<HTMLDialogElement>('#confirmar');

dialogo?.addEventListener('close', () => {
  abrir.focus();
});

type Estado = { carregando: boolean; erro?: string; dados?: string[] };

function tela(e: Estado): string {
  if (e.carregando && !e.dados) return 'esqueleto';
  if (e.erro) return 'erro + tentar de novo';
  if (!e.dados || e.dados.length === 0) return 'vazio + criar a primeira';
  return `lista (${e.dados.length})` + (e.carregando ? ' + atualizando' : '');
}

console.log(tela({ carregando: true }));
console.log(tela({ carregando: false, erro: 'sem rede' }));
console.log(tela({ carregando: false, dados: [] }));
console.log(tela({ carregando: false, dados: ['a', 'b'] }));
console.log(tela({ carregando: true, dados: ['a', 'b'] }));
